import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"位面穿越ルール","description":"","frontmatter":{},"headers":[],"relativePath":"ja/81-位面穿梭规则.md","filePath":"ja/81-位面穿梭规则.md","lastUpdated":null}'),l={name:"ja/81-位面穿梭规则.md"};function i(o,t,h,n,s,p){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="位面穿越ルール" tabindex="-1">位面穿越ルール <a class="header-anchor" href="#位面穿越ルール" aria-label="Permalink to &quot;位面穿越ルール&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>81</td></tr><tr><td>所属モジュール</td><td>跨位面インタラクションと時間ルール</td></tr><tr><td>コアキーワード</td><td>位面穿越、穿越許可、エネルギー閾値、アンカー校正、汚染防止</td></tr></tbody></table><h2 id="第一節-穿越行為の法的位置づけ" tabindex="-1">第一節 穿越行為の法的位置づけ <a class="header-anchor" href="#第一節-穿越行為の法的位置づけ" aria-label="Permalink to &quot;第一節 穿越行為の法的位置づけ&quot;">​</a></h2><p>位面穿越とは、生命の個体または集団が技術的手段または修錬能力を通じて、法則障壁を越えて一方の位面から他方の位面に入る行為を指す。アンカー共生文明の法的枠組みの下で、位面穿越は「高リスク特殊行為」に分類され、厳格な許可管理とプロセス監督の対象とならなければならない。「共生憲法」第四十七条は明確に規定している:「いかなる組織および個人も、許可なしに勝手に跨位面穿越を行ってはならず、位面穿越を利用して他の位面文明に対する略奪、干渉または汚染活動を行ってはならない。」</p><p>位面穿越が厳格な管理を必要とする根本的な理由は、穿越行為自体が目標位面に多重の影響を与える可能性があることである: 法則攪乱、エネルギー注入、意識汚染、微生物侵入、文化干渉など。これらの影響は軽度では目標位面の局所的異常を引き起こし、重度ではその文明の進化軌跡を変更し、さらには法則崩壊を引き起こす可能性がある。したがって、穿越ルールの核心目標は「穿越行為の外部影響を許容可能な閾値内に制御すること」である。</p><h2 id="第二節-穿越許可分級制度" tabindex="-1">第二節 穿越許可分級制度 <a class="header-anchor" href="#第二節-穿越許可分級制度" aria-label="Permalink to &quot;第二節 穿越許可分級制度&quot;">​</a></h2><p>衡元宙は位面穿越許可分級制度を実施しており、穿越目的、目標位面タイプ、穿越者の資質に応じて許可を四つのレベルに分類する:</p><table tabindex="0"><thead><tr><th>許可レベル</th><th>適用シナリオ</th><th>審査機関</th><th>有効期間</th><th>附加条件</th></tr></thead><tbody><tr><td>A級（考古観測）</td><td>純粋な観測性考古、いかなる物理的接触も行わない</td><td>位面管理局</td><td>単回任務</td><td>複製鏡+隔離空間スキームを使用しなければならない</td></tr><tr><td>B級（学術交流）</td><td>目標位面文明と限定的な知識交流を行う</td><td>位面管理局+文化部</td><td>最長一年</td><td>相互不干渉協定を締結しなければならない</td></tr><tr><td>C級（資源協力）</td><td>平等互恵の前提の下で資源と技術の協力を行う</td><td>アンカー議事会特批</td><td>最長三年</td><td>目標位面文明の同意を得なければならない</td></tr><tr><td>D級（緊急介入）</td><td>目標位面が絶滅級危機に直面した場合の人道的介入</td><td>アンカー議事会緊急決議</td><td>危機継続期間</td><td>事後に完全な介入報告書を提出しなければならない</td></tr></tbody></table><p>いかなるレベルの穿越許可も以下の行為を禁止する: 目標位面の本源エネルギーを略奪すること、自位面のイデオロギーを強制的に伝播すること、同意なしに遺伝子または意識改造を行うこと、目標位面に恒久的な軍事基地を建設すること、およびいかなる形の植民地支配。</p><h2 id="第三節-穿越技術要件とエネルギー閾値" tabindex="-1">第三節 穿越技術要件とエネルギー閾値 <a class="header-anchor" href="#第三節-穿越技術要件とエネルギー閾値" aria-label="Permalink to &quot;第三節 穿越技術要件とエネルギー閾値&quot;">​</a></h2><p>位面穿越には厳格な技術条件を満たす必要がある。まず、穿越者は「空間法理調度体系」第三階（化空境）以上の修錬を有するか、基準に適合した位面穿越車両を搭載しなければならない。次に、穿越の起点と終点の両方にアンカーによる座標校正が必要であり、アンカー測位のない盲目的穿越は厳格に禁止されている。</p><p>穿越プロセスのエネルギー消費は、目標位面の法則障壁の強度に正比例する。衡元宙は標準化された「穿越エネルギー閾値表」を確立しており、異なるタイプの位面の穿越に必要な最低エネルギーは以下の通りである:</p><ul><li>物質本位面: 1000標準エネルギー単位</li><li>エネルギー顕化位面: 5000標準エネルギー単位</li><li>意識主導位面: 20000標準エネルギー単位</li><li>法則破碎位面: 50000標準エネルギー単位（かつ成功率30%未満）</li><li>本源近隣位面: 理論値100000以上、現在成功記録なし</li></ul><p>穿越エネルギーは穿越者または車両自身が携帯しなければならず、穿越プロセスのために目標位面からエネルギーを抽出することは禁止されている。この規定は、穿越行為が目標位面にエネルギー略奪を引き起こすことを防止することを目的としている。</p><h2 id="第四節-穿越プロセスの汚染防止" tabindex="-1">第四節 穿越プロセスの汚染防止 <a class="header-anchor" href="#第四節-穿越プロセスの汚染防止" aria-label="Permalink to &quot;第四節 穿越プロセスの汚染防止&quot;">​</a></h2><p>位面穿越の最大のリスクの一つは「跨位面汚染」であり、生物汚染（自位面の微生物を携帯して目標位面に入る）、エネルギー汚染（自位面のエネルギー残留が目標位面の法則に干渉する）、意識汚染（穿越者の意識変動が目標位面の意識領域に影響を与える）を含む。</p><p>汚染を防止するため、すべての穿越者は出発前に「三級浄化プログラム」を完了しなければならない:</p><ol><li><strong>生物浄化</strong>: 隔離空間内で72時間の微生物スクリーニングと除去を行い、自位面の病原体を一切携帯していないことを確保する</li><li><strong>エネルギー浄化</strong>: アンカー校正装置を通じて穿越者のエネルギー周波数を目標位面と互換性のある範囲に調整し、エネルギー拒絶反応を減らす</li><li><strong>意識浄化</strong>: 意識遮断トレーニングを行い、穿越プロセス中に目標位面の意識領域に干渉する可能性のある意念変動を能動的に放出しないことを確保する</li></ol><p>さらに、目標位面における穿越者の活動範囲は「穿越許可画定区域」内に厳格に限定され、無許可の拡散は禁止されている。自位面に戻った後、穿越者は再び隔離観察を受けなければならず、期間は目標位面の時間流速で換算した30日以上である。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>位面穿越ルールは跨位面インタラクションの第一道の安全防衛線である。許可分級、技術門檻、汚染防止の三重のメカニズムを通じて、穿越行為が常に「低影響、追跡可能、問責可能」の軌道で運行されることを確保する。ルールの究極的な目的は文明間の交流を制限することではなく、交流が略奪の方式ではなく共生の方式で行われるようにすることである。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>80-位面理論と分類</li><li>88-跨位面倫理準則</li><li>62-空間法理技術実現</li></ul>',23)])])}const b=a(l,[["render",i]]);export{c as __pageData,b as default};
